/**
 * Accessibility and Security Types
 *
 * Type definitions for accessible and secure component development.
 *
 * @module @dsai-io/react/types/accessibility
 */

import type { CSSProperties } from 'react';

/**
 * Safe HTML attributes whitelist
 *
 * SECURITY: Prevents injection of dangerous attributes or event handlers
 *
 * This interface provides a whitelist of HTML attributes that are safe to spread
 * onto components. It explicitly excludes event handlers (onClick, onMouseOver, etc.)
 * and other potentially dangerous attributes to prevent XSS attacks.
 *
 *
 * @template T - HTML element type for element-specific attributes
 *
 * @example
 * ```typescript
 * interface ButtonProps extends SafeHTMLAttributes<HTMLButtonElement> {
 *   variant?: ButtonVariant;
 *   size?: ComponentSize;
 * }
 *
 * // Component can safely spread safe props
 * <button {...safeProps} className={className} />
 * ```
 */
export interface SafeHTMLAttributes<_T extends HTMLElement = HTMLElement> {
  // Standard HTML attributes
  className?: string;
  style?: CSSProperties;
  id?: string;

  // Test identifiers
  'data-testid'?: string;
  'data-test'?: string;

  // Descriptive
  title?: string;

  // Interaction
  tabIndex?: number;

  // ARIA - Core
  role?: string;
  'aria-roledescription'?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
  'aria-describedby'?: string;

  // ARIA - State
  'aria-hidden'?: boolean | 'true' | 'false';
  'aria-expanded'?: boolean | 'true' | 'false';
  'aria-selected'?: boolean | 'true' | 'false';
  'aria-checked'?: boolean | 'true' | 'false' | 'mixed';
  'aria-disabled'?: boolean | 'true' | 'false';
  'aria-pressed'?: boolean | 'true' | 'false' | 'mixed';
  'aria-current'?: boolean | 'true' | 'false' | 'page' | 'step' | 'location' | 'date' | 'time';
  'aria-busy'?: boolean | 'true' | 'false';

  // ARIA - Form validation (WCAG 2.2 AA)
  'aria-invalid'?: boolean | 'true' | 'false' | 'grammar' | 'spelling';
  'aria-required'?: boolean | 'true' | 'false';
  'aria-errormessage'?: string;

  // ARIA - Relationships
  'aria-controls'?: string;
  'aria-owns'?: string;
  'aria-activedescendant'?: string;

  // ARIA - Live regions
  'aria-live'?: 'off' | 'polite' | 'assertive';
  'aria-atomic'?: boolean | 'true' | 'false';
  'aria-relevant'?: 'additions' | 'removals' | 'text' | 'all';

  // ARIA - Drag and drop
  'aria-dropeffect'?: 'none' | 'copy' | 'move' | 'link' | 'execute' | 'popup';
  'aria-grabbed'?: boolean | 'true' | 'false';

  // Custom data attributes (allow any data-* attribute)
  // Safe because data attributes cannot execute JavaScript
  [key: `data-${string}`]: string | number | boolean | undefined;
}

/**
 * Common ARIA properties for interactive components
 *
 * Subset of ARIA attributes commonly used for component accessibility.
 * Use SafeHTMLAttributes for components that need the full whitelist.
 *
 * @example
 * ```typescript
 * interface TooltipProps extends ARIAProps {
 *   content: ReactNode;
 * }
 * ```
 */
export interface ARIAProps {
  role?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
  'aria-describedby'?: string;
  'aria-expanded'?: boolean;
  'aria-selected'?: boolean;
  'aria-checked'?: boolean | 'mixed';
  'aria-disabled'?: boolean;
  'aria-hidden'?: boolean;
  'aria-controls'?: string;
  'aria-haspopup'?: boolean | 'menu' | 'listbox' | 'tree' | 'grid' | 'dialog';
  'aria-live'?: 'off' | 'polite' | 'assertive';
}

/**
 * Finite State Machine (FSM) Base Types
 *
 * Type definitions for implementing finite state machines in components.
 * These types provide a consistent pattern for state management across components.
 *
 * @module @dsai-io/react/types/fsm
 */

/**
 * Base interface for Finite State Machine states
 *
 * PERFORMANCE: Keep minimal - FSM updates happen frequently
 * SCALABILITY: Use discriminated unions for state variants
 *
 * Used by: Toast, Popover, Accordion, CardList, Carousel, TabsPro, Table,
 * Tooltip, Navbar, CheckboxGroup, Scrollspy
 *
 * @example
 * ```typescript
 * interface ToastFSMState extends FSMStateBase {
 *   visibility: 'hidden' | 'entering' | 'visible' | 'exiting';
 *   shouldRender: boolean;
 * }
 * ```
 */
export interface FSMStateBase {
  /**
   * Current state identifier
   * Use discriminated union for type safety
   */
  status?: string;
}

/**
 * Base interface for FSM events
 *
 * ⚠️ PERFORMANCE: Events should be lightweight POJOs
 * ⚠️ BEST PRACTICE: Use discriminated unions with 'type' field
 *
 * @example
 * ```typescript
 * type ToastFSMEvent =
 *   | { type: 'SHOW' }
 *   | { type: 'HIDE' }
 *   | { type: 'DISMISS' }
 *   | { type: 'ANIMATION_END' };
 * ```
 */
export interface FSMEventBase {
  /**
   * Event type identifier (discriminant)
   */
  type: string;
}

/**
 * FSM Reducer function signature
 *
 * Pure function that takes current state and event, returns new state.
 * Must be pure (no side effects, same input always produces same output).
 *
 * @template State - FSM state type
 * @template Event - FSM event type
 *
 * @example
 * ```typescript
 * const reducer: FSMReducer<ToastFSMState, ToastFSMEvent> = (state, event) => {
 *   switch (event.type) {
 *     case 'SHOW':
 *       return { ...state, visibility: 'entering', shouldRender: true };
 *     case 'HIDE':
 *       return { ...state, visibility: 'exiting' };
 *     default:
 *       return state;
 *   }
 * };
 * ```
 */
export type FSMReducer<State extends FSMStateBase, Event extends FSMEventBase> = (
  state: State,
  event: Event
) => State;

/**
 * FSM Configuration
 *
 * Configuration object for setting up a finite state machine.
 * Includes initial state and reducer function.
 *
 * @template State - FSM state type
 * @template Event - FSM event type
 *
 * @example
 * ```typescript
 * const toastFSMConfig: FSMConfig<ToastFSMState, ToastFSMEvent> = {
 *   initialState: { visibility: 'hidden', shouldRender: false },
 *   reducer: toastReducer,
 * };
 * ```
 */
export interface FSMConfig<State extends FSMStateBase, Event extends FSMEventBase> {
  /**
   * Initial state of the state machine
   */
  initialState: State;

  /**
   * Reducer function to handle state transitions
   */
  reducer: FSMReducer<State, Event>;
}

/**
 * Visual state derived from FSM state
 *
 * Used for CSS classes and rendering decisions.
 * Keeps FSM state minimal while providing rich rendering info.
 *
 * ⚠️ PERFORMANCE: Derive this on-demand, don't store in FSM state
 *
 * @example
 * ```typescript
 * function getVisualState(fsmState: ToastFSMState): VisualStateBase {
 *   return {
 *     state: fsmState.visibility,
 *     shouldRender: fsmState.shouldRender,
 *     modifiers: fsmState.visibility === 'visible' ? ['active'] : undefined,
 *   };
 * }
 * ```
 */
export interface VisualStateBase {
  /**
   * Primary visual state (maps to CSS classes)
   */
  state: string;

  /**
   * Whether component should be in DOM
   */
  shouldRender: boolean;

  /**
   * Optional CSS class modifiers
   */
  modifiers?: string[];
}

/**
 * DSAi React - Centralized Type System
 *
 * Shared type primitives for component development.
 * Reduces duplication and ensures consistency across the design system.
 *
 * This module provides core type definitions that are used across multiple
 * components, eliminating duplication and establishing a single source of truth
 * for design system primitives.
 *
 * @module @dsai-io/react/types
 *
 * @example
 * ```typescript
 * // Import from types module
 * import type { SemanticColorVariant, ComponentSize } from '@dsai-io/react/types';
 *
 * // Or from main package (after export updates)
 * import type { SemanticColorVariant } from '@dsai-io/react';
 *
 * // Use in component types
 * interface AlertProps {
 *   variant?: SemanticColorVariant;
 *   size?: ComponentSize;
 * }
 * ```
 */

// =============================================================================
// Core Primitives
// =============================================================================

export type {
  Alignment,
  ComponentSize,
  ExtendedSize,
  FeedbackVariant,
  Orientation,
  SemanticColorVariant,
} from './primitives';

// =============================================================================
// Accessibility & Security
// =============================================================================

export type { ARIAProps, SafeHTMLAttributes } from './accessibility';

// =============================================================================
// State Machines
// =============================================================================

export type { FSMConfig, FSMEventBase, FSMReducer, FSMStateBase, VisualStateBase } from './fsm';

// =============================================================================
// Polymorphic Components
// =============================================================================

export type { PolymorphicComponentProps, PolymorphicProps, PolymorphicRef } from './polymorphic';

// =============================================================================
// Responsive Values
// =============================================================================

export type { Breakpoint, ResponsiveProp, ResponsiveValue } from './responsive';

/**
 * @deprecated Import runtime helpers from `@dsai-io/react/utils/responsive` to keep the types barrel type-only.
 */
export { getResponsiveValue, isResponsiveValue } from './responsive';

/**
 * Core Design System Primitives
 *
 * Shared type primitives for component development.
 * These types eliminate duplication and ensure consistency across components.
 *
 * @module @dsai-io/react/types/primitives
 */

/**
 * Semantic color variants used across components
 *
 * @example
 * ```typescript
 * // Direct reuse
 * type AlertVariant = SemanticColorVariant;
 *
 * // Extended with additional variants
 * type ButtonVariant = SemanticColorVariant | `outline-${SemanticColorVariant}` | 'link';
 * ```
 */
export type SemanticColorVariant =
  | 'primary'
  | 'secondary'
  | 'success'
  | 'danger'
  | 'warning'
  | 'info'
  | 'light'
  | 'dark';

/**
 * Standard component sizing scale
 *
 * @example
 * ```typescript
 * type ButtonSize = ComponentSize;
 * type InputSize = ComponentSize;
 * ```
 */
export type ComponentSize = 'sm' | 'md' | 'lg';

/**
 * Extended size scale for components needing finer granularity
 *
 * Used by: Avatar, Spinner, Modal
 *
 * @example
 * ```typescript
 * // Full extended size
 * type AvatarSize = ExtendedSize;
 *
 * // Subset without '2xl' or 'xxl'
 * type SpinnerSize = Exclude<ExtendedSize, '2xl' | 'xxl'>;
 *
 * // Extended with custom sizes
 * type ModalSize = ComponentSize | 'xl' | 'fullscreen';
 * ```
 */
export type ExtendedSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl' | 'xxl';

/**
 * Feedback/notification variants
 *
 * Used by: Toast, notification systems
 * Note: Uses 'error' instead of 'danger' for feedback semantics
 *
 * @example
 * ```typescript
 * type ToastVariant = FeedbackVariant;
 * ```
 */
export type FeedbackVariant = 'success' | 'error' | 'warning' | 'info' | 'default';

/**
 * Alignment options for layout components
 *
 * @example
 * ```typescript
 * interface FlexProps {
 *   align?: Alignment;
 *   justify?: Alignment;
 * }
 * ```
 */
export type Alignment = 'start' | 'center' | 'end';

/**
 * Orientation for components that support both directions
 *
 * @example
 * ```typescript
 * interface TabsProps {
 *   orientation?: Orientation;
 * }
 * ```
 */
export type Orientation = 'horizontal' | 'vertical';

/**
 * Responsive Value Types
 *
 * Type definitions for responsive values that support breakpoint-specific values.
 * Allows components to adapt to different screen sizes.
 *
 * @module @dsai-io/react/types/responsive
 */

/**
 * Breakpoint identifiers
 *
 * Matches Bootstrap 5 breakpoints (aligned with DSAi design tokens):
 * - xs: 0px (extra small, mobile)
 * - sm: >= 576px (small, large mobile)
 * - md: >= 768px (medium, tablets)
 * - lg: >= 992px (large, desktops)
 * - xl: >= 1200px (extra large, large desktops)
 * - xxl: >= 1400px (extra extra large, wide screens)
 *
 * @see {@link https://getbootstrap.com/docs/5.3/layout/breakpoints/}
 */
export type Breakpoint = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | 'xxl';

/**
 * Responsive value that supports breakpoint-specific values
 *
 * Allows a value to be either:
 * 1. A single value (applied at all breakpoints)
 * 2. An object with breakpoint-specific values
 *
 * @template T - Value type
 *
 * @example
 * ```typescript
 * interface CardProps {
 *   columns?: ResponsiveValue<1 | 2 | 3 | 4>;
 *   gap?: ResponsiveValue<number>;
 * }
 *
 * // Single value (non-responsive)
 * <Card columns={2} />
 *
 * // Responsive values (Bootstrap 5 breakpoints)
 * <Card columns={{ xs: 1, md: 2, lg: 3 }} />
 * <Card gap={{ xs: 8, md: 16, xl: 24 }} />
 * ```
 */
export type ResponsiveValue<T> =
  | T
  | {
      xs?: T;
      sm?: T;
      md?: T;
      lg?: T;
      xl?: T;
      xxl?: T;
    };

/**
 * Responsive prop helper type
 *
 * Shorthand for making a prop responsive.
 *
 * @template T - Value type
 *
 * @example
 * ```typescript
 * interface GridProps {
 *   columns: ResponsiveProp<number>;
 *   gap: ResponsiveProp<string>;
 * }
 * ```
 */
export type ResponsiveProp<T> = ResponsiveValue<T>;

// =============================================================================
// Runtime Utilities (re-exported from utils/responsive for backward compatibility)
// =============================================================================

/**
 * Runtime utilities for responsive values
 *
 * These functions are implemented in utils/responsive and re-exported here
 * for backward compatibility. New code should import from utils/responsive.
 *
 * @see {@link module:@dsai-io/react/utils/responsive}
 * @deprecated Import from `@dsai-io/react/utils/responsive` to keep type modules type-only.
 */
